DROP TABLE IF EXISTS dbo.[fact_monthly_kpi];
CREATE TABLE dbo.[fact_monthly_kpi]
(
    [MonthStart] DATE NOT NULL,
    [BranchId] VARCHAR(20) NOT NULL,
    [Region] VARCHAR(20) NULL,
    [LoansBooked] INT NULL,
    [DepositGrowthPct] FLOAT NULL,
    [NPS] FLOAT NULL,
    [DelinquencyRatePct] FLOAT NULL,
    [DigitalAdoptionPct] FLOAT NULL,
    CONSTRAINT [PK_fact_monthly_kpi] PRIMARY KEY ([MonthStart], [BranchId])
);
GO

