DROP TABLE IF EXISTS dbo.[glossary_kpi_definitions];
CREATE TABLE dbo.[glossary_kpi_definitions]
(
    [KPI] VARCHAR(50) NOT NULL,
    [Definition] VARCHAR(400) NULL,
    [Owner] VARCHAR(100) NULL,
    [Calculation] VARCHAR(400) NULL,
    CONSTRAINT [PK_glossary_kpi_definitions] PRIMARY KEY ([KPI])
);
GO

INSERT INTO dbo.[glossary_kpi_definitions] ([KPI], [Definition], [Owner], [Calculation]) VALUES
('LoansBooked', 'Count of newly funded consumer and small-business loans in the month.', 'Retail Finance', 'SUM(FactMonthlyKPI[LoansBooked])'),
('DepositGrowthPct', 'Month-over-month percentage growth of total deposit balances.', 'Treasury Analytics', '(CurrentMonthDeposits-PriorMonthDeposits)/PriorMonthDeposits'),
('NPS', 'Net Promoter Score based on member post-interaction survey responses.', 'Member Experience', 'Promoters% - Detractors%'),
('DelinquencyRatePct', 'Share of loan balances 60+ days past due, excluding credit cards.', 'Credit Risk', 'Delinquent60PlusBalance/TotalLoanBalanceExCards'),
('DigitalAdoptionPct', 'Percent of active members who used at least one digital channel in the month.', 'Digital Banking', 'DigitalActiveMembers/ActiveMembers');
GO

